</tool_q7OT><tool_result_HcDw name="linux_ssh:linux_ssh_exec" status="success"><content>{"packageVersion":"0.1.0","success":true,"timeoutMs":15000,"exitCode":0,"timedOut":false,"output":"/* ========== 左栏文件树样式 ========== */
.sidebar{position:fixed;top:0;left:0;width:280px;height:100%;background:var(--surface);z-index:1000;transform:translateX(-100%);transition:transform .35s cubic-bezier(.34,1.56,.64,1)}
.sidebar.open{transform:translateX(0)}
.sidebar-header{display:none}
.sidebar-content{position:relative;height:calc(100% - 44px);overflow-y:auto;padding:8px}
.sidebar-tools{position:absolute;bottom:0;left:0;right:0;padding:6px 8px;background:rgba(30,30,40,.85);border-top:2px solid var(--primary);display:flex;gap:8px;align-items:center;box-shadow:0 -4px 12px rgba(0,0,0,.3);backdrop-filter:blur(8px)}
.sidebar-path{flex:0 1 auto;min-width:0;max-width:100%;font-size:12px;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding:4px 8px;background:rgba(46,213,163,.15);border-left:3px solid var(--accent);border-radius:4px}
.sidebar-tools button{flex-shrink:0;width:36px;height:28px;background:rgba(124,58,237,.1);border:none;border-left:2px solid var(--primary);border-radius:6px;font-size:16px;color:var(--text);cursor:pointer;display:flex;align-items:center;justify-content:center;box-shadow:-2px 0 6px rgba(0,0,0,.2);transition:all .15s}
.sidebar-tools button:active{background:rgba(124,58,237,.2);transform:scale(.95)}
.sidebar-tools button.active{border-color:var(--accent);background:rgba(124,58,237,.25)}

/* 树节点 */
.tree-item{cursor:pointer;font-size:13px;position:relative;outline:none;overflow:visible}
.tree-row{display:flex;align-items:center;padding:4px 8px;border-radius:4px;position:relative;border-left:3px solid transparent}

/* 光标高亮条（独立元素，浮动在文件树上方） */
.cursor-highlight{
  position:absolute;
  height:32px;
  background:rgba(46,213,163,.15);
  border-left:3px solid var(--accent);
  border-radius:4px;
  z-index:1050;
  pointer-events:none;
  transition:top .3s cubic-bezier(.25,.46,.45,.94),left .3s cubic-bezier(.25,.46,.45,.94),width .3s cubic-bezier(.25,.46,.45,.94);
}
.tree-toggle{width:18px;height:18px;margin-right:6px;display:inline-block;vertical-align:middle;flex-shrink:0}
.tree-toggle::before{content:'▶';font-size:10px;color:var(--accent);display:inline-block;transition:transform .2s}
.tree-toggle.expanded::before{transform:rotate(90deg)}
.tree-toggle.hidden{opacity:0}
.tree-name{font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;user-select:none;flex:1;min-width:0}
.tree-name.link{color:var(--accent);font-style:italic}

/* 新建/重命名输入框 - 盒子样式 */
.tree-input-wrap{
  display:flex;align-items:center;gap:4px;padding:4px 8px;
  border-radius:8px;
  z-index:1010;
  box-shadow:-2px 0 12px rgba(0,0,0,.4)
}
/* 重命名编辑框 - fixed 定位，宽度固定为 sidebar 宽度，盒子样式 */
.tree-input-wrap.tree-input-overlay{
  position:fixed;
  height:40px;
  background:rgba(30,30,40,.85);
  border-left:3px solid var(--primary);
  border-radius:8px;
  z-index:1300;
  backdrop-filter:blur(8px)
}
.tree-input{flex:1;background:var(--bg);border:1px solid var(--primary);border-radius:4px;padding:4px 8px;color:var(--text);font-size:13px;outline:none;min-width:0}
.tree-input-btn{width:28px;height:28px;border:none;border-radius:8px;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:14px;transition:all .15s;box-shadow:-2px 0 8px rgba(0,0,0,.3);flex-shrink:0}
.tree-input-btn.confirm{background:rgba(46,213,163,.15);color:#2ed5a3;border-left:3px solid #2ed5a3}
.tree-input-btn.cancel{background:rgba(255,71,117,.15);color:#ff4775;border-left:3px solid #ff4775}
.tree-input-btn:active{transform:scale(.9)}

/* Grid展开动画：Q弹效果+立体感 */
.tree-children-wrap{display:grid;grid-template-rows:0fr;margin-left:10px;border-left:2px solid;border-radius:4px;transition:grid-template-rows .3s cubic-bezier(.34,1.56,.64,1);box-shadow:-2px 0 8px rgba(0,0,0,.3)}
.tree-children-wrap>div{overflow:hidden;transform-origin:top}
.tree-children-wrap.open{grid-template-rows:1fr}
.tree-children-wrap.open>div{padding:2px 0 2px 8px;animation:q弹-in .35s cubic-bezier(.34,1.56,.64,1) .15s both}
@keyframes q弹-in{
  0%{transform:scaleY(0);opacity:0}
  60%{transform:scaleY(1.05)}
  100%{transform:scaleY(1);opacity:1}
}


/* 加载占位动画 */
.loading-pulse{padding:8px}
.pulse-row{height:24px;background:linear-gradient(90deg,rgba(124,58,237,.1) 25%,rgba(124,58,237,.2) 50%,rgba(124,58,237,.1) 75%);background-size:200% 100%;animation:pulse 1.5s ease-in-out infinite;border-radius:4px;margin-bottom:8px}
@keyframes pulse{0%{background-position:200% 0}100%{background-position:-200% 0}}

/* 文件行暗化 */
.tree-item.dimmed .tree-name{opacity:.4}

/* 日志面板 */
.log-panel{position:fixed;top:0;right:0;width:85%;max-width:360px;height:100%;background:var(--surface);z-index:1400;transform:translateX(100%);transition:transform .3s cubic-bezier(.34,1.56,.64,1);display:flex;flex-direction:column}
.log-panel.open{transform:translateX(0)}
.log-header{display:flex;justify-content:space-between;align-items:center;padding:12px 16px;border-bottom:1px solid var(--border)}
.log-title{font-size:16px;font-weight:600;color:var(--text)}
.log-content{flex:1;overflow-y:auto;padding:8px;font-family:monospace;font-size:12px}
.log-item{padding:6px 8px;margin-bottom:4px;border-radius:4px;background:rgba(0,0,0,.3);border-left:3px solid var(--primary);word-break:break-all}
.log-item.error{border-color:#ff4775;background:rgba(255,71,117,.1)}
.log-item.success{border-color:#2ed5a3;background:rgba(46,213,163,.1)}
.log-item .time{color:var(--accent);font-size:10px;margin-right:6px}","sessionId":"","error":""}</content></tool_result_HcDw>

