new_css = &apos;&apos;&apos;.tree-children-wrap.open&gt;div{padding:2px 0 2px 8px;animation:q弹-in .35s cubic-bezier(.34,1.56,.64,1) .15s both}

/* 边框粒子：方形发光光点沿 border-left 流动 */
.tree-children-wrap.open::before{
  content:&apos;&apos;;
  position:absolute;
  left:-1px;
  width:4px;
  height:4px;
  background:currentColor;
  box-shadow:0 0 4px currentColor,0 0 8px currentColor;
