}
@keyframes border-flow{
  0%{top:0;opacity:0}
  5%{opacity:1}
  90%{opacity:1}
  100%{top:calc(100% - 4px);opacity:0}
}&apos;&apos;&apos;

content = content.replace(old, new_css)

with open(&apos;css/sidebar.css&apos;, &apos;w&apos;) as f:
    f.write(content)

print(&apos;CSS updated&apos;)
PYEOF&quot;}</param>
